// Builds the ImageFlow disk image: the app, an Applications shortcut, and the branded Finder window from resources/dmg/.
// The window layout (resources/dmg/DS_Store) is generated by scripts/build-dmg-layout.py; see that file to change it.
// Run directly to build an unsigned preview: node scripts/mac-dmg.mjs [ImageFlow.app] [out.dmg]
import { copyFile, mkdir, mkdtemp, rm, symlink } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { packagedMacApp } from './mac-paths.mjs';
import { run } from './verify-mac-signing.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const dmg = join(root, 'resources', 'dmg');

export async function createMacDmg(app, image, work) {
  const contents = join(work, 'contents');
  await mkdir(contents);
  // ditto preserves the bundle's signed resources and stapled ticket.
  await run('ditto', [app, join(contents, 'ImageFlow.app')]);
  await symlink('/Applications', join(contents, 'Applications'));
  // One TIFF with both resolutions lets Finder pick the sharp one on Retina displays.
  await run('tiffutil', ['-cathidpicheck', join(dmg, 'background.png'), join(dmg, 'background@2x.png'),
    '-out', join(contents, '.background.tiff')]);
  // The layout refers to /.background.tiff on a volume named ImageFlow; keep -volname in step with it.
  await copyFile(join(dmg, 'DS_Store'), join(contents, '.DS_Store'));
  await run('hdiutil', ['create', '-volname', 'ImageFlow', '-srcfolder', contents, '-fs', 'HFS+', '-format', 'UDZO', image]);
  return image;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const app = resolve(process.argv[2] ?? packagedMacApp(root));
  const image = resolve(process.argv[3] ?? join(root, 'out', 'ImageFlow-preview.dmg'));
  await mkdir(join(root, '.build'), { recursive: true });
  const work = await mkdtemp(join(root, '.build', 'dmg-'));
  try {
    await rm(image, { force: true });
    console.log('Preview DMG: ' + await createMacDmg(app, image, work));
  } finally {
    await rm(work, { recursive: true, force: true });
  }
}
